// План specs/gps-workflow.md 6.1 (#98c982). PROD, gps (компания «בדיקה»), десктоп, EN.
// @writes @data: назначает на существующую работу (по умолчанию JOB-0020, QA_GPS_JOB) техника БЕЗ SMS-согласия (по умолчанию «QA-Tech Gamma»,
// QA_GPS_NO_SMS_TECH) и тут же снимает его. SMS никому не уходит: у такого техника согласия нет — именно это и проверяется.
// Источник: «מה רצוי» — если у техника нет согласия на SMS (или телефона) — сразу «No SMS», без шага «SMS pending».
// Факты 17.11: сразу «No SMS», «SMS pending» не появлялся. Не сверено с сайтом при записи: техник QA-Tech Gamma в компании gps (имя берётся из env),
// строка истории — как на странице работы admin (assignment-helpers). Ожидание 2 минут не воспроизводится: проверяем 10 секунд подряд.
import { test, expect } from '../../fixtures';
import { assignCombo, assignTech, ensureNoTechnician, expectLatestHistory, latestHistoryEntry } from '../job-assignment/assignment-helpers';
import { ROLE, prepare } from './gps-helpers';

const JOB = process.env.QA_GPS_JOB || 'JOB-0020';
const TECH = process.env.QA_GPS_NO_SMS_TECH || 'QA-Tech Auto';

test.describe('Assignment history — technician without SMS consent (#98c982)', () => {
  test('Assign a technician without SMS consent: history shows "No SMS" at once and never "SMS pending" #98c982 @desktop @writes @data', async ({ asUser }) => {
    test.setTimeout(150_000);
    const page = await asUser(ROLE);
    await prepare(page);
    page.on('dialog', (d) => (d.type() === 'beforeunload' ? d.accept() : d.dismiss()).catch(() => {}));
    await page.goto('/jobs');
    await page.getByPlaceholder(/^Search jobs/i).fill(JOB);
    await page.locator('tr', { hasText: JOB }).first().click();
    await page.waitForURL(/\/JobDetail\?id=/i, { timeout: 30_000 });
    await expect(assignCombo(page)).toBeVisible({ timeout: 30_000 });
    try {
      await ensureNoTechnician(page);
      await assignTech(page, TECH);
      await expectLatestHistory(page, `Assigned to ${TECH}`);
      const entry = latestHistoryEntry(page);
      await expect(entry.getByText('No SMS', { exact: true }), 'сразу «No SMS»').toBeVisible({ timeout: 5_000 });
      // 10 секунд: «SMS pending» не появляется, «No SMS» остаётся
      for (let i = 0; i < 5; i++) {
        await expect(entry.getByText(/SMS pending/i)).toHaveCount(0);
        await page.waitForTimeout(2_000);
      }
      await expect(entry.getByText('No SMS', { exact: true })).toBeVisible();
    } finally {
      await ensureNoTechnician(page).catch(() => {});
    }
  });
});
